// client says upload to object storage finished
async function finalizeUpload(req) {
  const { videoId, ownerId } = req.body;
  await metadata.insert({ videoId, ownerId, status: 'ready' }); // mark ready
  await transcodeQueue.enqueue({ videoId });                    // start transcoding
  return { ok: true };
}
